using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using LifeVerse.Api.Data;
using LifeVerse.Api.Modules.Worlds;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Discovery;

public sealed record LandmarkRequest(string Name, Guid IslandId, float PositionX, float PositionY, float PositionZ, float RotationY, bool IsPublic);
public sealed record EventRequest(string Name, string Description, Guid IslandId, DateTimeOffset StartsAt, DateTimeOffset EndsAt, int Capacity, bool IsPublic);
public sealed record SnapshotRequest(Guid? IslandId, string StorageKey, string MetadataJson, bool IsPublic);

public static class DiscoveryEndpoints
{
    public static IEndpointRouteBuilder MapDiscoveryEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/discovery").WithTags("Discovery").RequireAuthorization();
        group.MapGet("/islands", SearchIslandsAsync); group.MapPost("/islands/{islandId:guid}/favorite", FavoriteAsync); group.MapDelete("/islands/{islandId:guid}/favorite", UnfavoriteAsync); group.MapPost("/islands/{islandId:guid}/teleport", TeleportAsync);
        group.MapGet("/landmarks", ListLandmarksAsync); group.MapPost("/landmarks", CreateLandmarkAsync); group.MapDelete("/landmarks/{id:guid}", DeleteLandmarkAsync);
        group.MapGet("/events", ListEventsAsync); group.MapPost("/events", CreateEventAsync); group.MapPost("/events/{eventId:guid}/join", JoinEventAsync); group.MapPost("/events/{eventId:guid}/leave", LeaveEventAsync);
        group.MapGet("/photos", ListPhotosAsync); group.MapPost("/photos", CreatePhotoAsync); group.MapDelete("/photos/{id:guid}", DeletePhotoAsync);
        return endpoints;
    }
    private static async Task<IResult> SearchIslandsAsync(string? q, string? category, string? sort, int page, int pageSize, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); page = Math.Max(1, page); pageSize = Math.Clamp(pageSize == 0 ? 24 : pageSize, 1, 100); var query = db.Islands.AsNoTracking().Where(x => x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == me)); if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.Name.ToLower().Contains(q.ToLower()) || x.Description.ToLower().Contains(q.ToLower())); if (!string.IsNullOrWhiteSpace(category)) query = query.Where(x => x.Category == category); query = sort == "recent" ? query.OrderByDescending(x => x.CreatedAt) : sort == "popular" ? query.OrderByDescending(x => x.MaxPlayers).ThenByDescending(x => x.UpdatedAt) : query.OrderBy(x => x.Name); var total = await query.CountAsync(ct); var rows = await query.Skip((page - 1) * pageSize).Take(pageSize).Select(x => new { x.Id, x.Name, x.Description, x.CoverImageUrl, x.Category, x.IsPublic, x.MaxPlayers, x.RuntimeState, x.CreatedAt }).ToListAsync(ct); return Results.Ok(new { page, pageSize, total, items = rows }); }
    private static async Task<IResult> FavoriteAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == me), ct)) return Results.NotFound(); if (!await db.IslandFavorites.AnyAsync(x => x.UserId == me && x.IslandId == islandId, ct)) { db.IslandFavorites.Add(new IslandFavorite { Id = Guid.NewGuid(), UserId = me, IslandId = islandId, CreatedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> UnfavoriteAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.IslandFavorites.SingleOrDefaultAsync(x => x.UserId == me && x.IslandId == islandId, ct); if (item is not null) { db.IslandFavorites.Remove(item); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> TeleportAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, WorldManager worlds, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == me || db.IslandPermissions.Any(p => p.IslandId == islandId && p.UserId == me && p.RevokedAt == null && p.Permission == "enter")), ct); if (island is null) return Results.NotFound(); var active = await db.TeleportReservations.CountAsync(x => x.IslandId == islandId && x.Status == "reserved" && x.ExpiresAt > clock.GetUtcNow(), ct); if (active >= island.MaxPlayers) return Results.Conflict(new { error = "island_full" }); var decision = await worlds.EnsureAsync(islandId, ct); var reservation = new TeleportReservation { Id = Guid.NewGuid(), UserId = me, IslandId = islandId, Status = decision?.State == "running" ? "reserved" : "pending", ExpiresAt = clock.GetUtcNow().AddSeconds(30), CreatedAt = clock.GetUtcNow() }; db.TeleportReservations.Add(reservation); await db.SaveChangesAsync(ct); return Results.Ok(new { reservationId = reservation.Id, state = reservation.Status, instance = decision }); }
    private static async Task<IResult> ListLandmarksAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); return Results.Ok(await db.Landmarks.AsNoTracking().Where(x => x.OwnerUserId == me && x.DeletedAt == null).ToListAsync(ct)); }
    private static async Task<IResult> CreateLandmarkAsync(LandmarkRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await CanEnter(db, request.IslandId, me, ct)) return Results.Forbid(); if (request.Name.Trim().Length is < 1 or > 120) return Results.BadRequest(); var item = new Landmark { Id = Guid.NewGuid(), OwnerUserId = me, IslandId = request.IslandId, Name = request.Name.Trim(), PositionX = request.PositionX, PositionY = request.PositionY, PositionZ = request.PositionZ, RotationY = request.RotationY, IsPublic = request.IsPublic, CreatedAt = clock.GetUtcNow() }; db.Landmarks.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/discovery/landmarks/{item.Id}", item); }
    private static async Task<IResult> DeleteLandmarkAsync(Guid id, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.Landmarks.SingleOrDefaultAsync(x => x.Id == id && x.OwnerUserId == me && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); item.DeletedAt = DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> ListEventsAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out _)) return Results.Unauthorized(); return Results.Ok(await db.DiscoveryEvents.AsNoTracking().Where(x => x.IsPublic && x.EndsAt >= DateTimeOffset.UtcNow).OrderBy(x => x.StartsAt).Take(100).ToListAsync(ct)); }
    private static async Task<IResult> CreateEventAsync(EventRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await db.Islands.AnyAsync(x => x.Id == request.IslandId && x.OwnerUserId == me && x.DeletedAt == null, ct) || request.StartsAt >= request.EndsAt || request.Capacity is < 1 or > 10000) return Results.BadRequest(); var item = new DiscoveryEvent { Id = Guid.NewGuid(), IslandId = request.IslandId, OrganizerUserId = me, Name = request.Name.Trim()[..Math.Min(160, request.Name.Trim().Length)], Description = request.Description[..Math.Min(4000, request.Description.Length)], StartsAt = request.StartsAt, EndsAt = request.EndsAt, Capacity = request.Capacity, IsPublic = request.IsPublic, CreatedAt = clock.GetUtcNow() }; db.DiscoveryEvents.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/discovery/events/{item.Id}", item); }
    private static async Task<IResult> JoinEventAsync(Guid eventId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var e = await db.DiscoveryEvents.SingleOrDefaultAsync(x => x.Id == eventId && x.EndsAt >= DateTimeOffset.UtcNow, ct); if (e is null) return Results.NotFound(); if (await db.EventAttendees.CountAsync(x => x.EventId == eventId, ct) >= e.Capacity) return Results.Conflict(new { error = "event_full" }); if (!await db.EventAttendees.AnyAsync(x => x.EventId == eventId && x.UserId == me, ct)) { db.EventAttendees.Add(new EventAttendee { Id = Guid.NewGuid(), EventId = eventId, UserId = me, JoinedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> LeaveEventAsync(Guid eventId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.EventAttendees.SingleOrDefaultAsync(x => x.EventId == eventId && x.UserId == me, ct); if (item is not null) { db.EventAttendees.Remove(item); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> ListPhotosAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); return Results.Ok(await db.PhotoSnapshots.AsNoTracking().Where(x => x.OwnerUserId == me || x.IsPublic).OrderByDescending(x => x.CreatedAt).Take(100).ToListAsync(ct)); }
    private static async Task<IResult> CreatePhotoAsync(SnapshotRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.StorageKey.Length is < 1 or > 512 || request.MetadataJson.Length > 8192) return Results.BadRequest(); try { using var json = JsonDocument.Parse(request.MetadataJson); } catch { return Results.BadRequest(); } var item = new PhotoSnapshot { Id = Guid.NewGuid(), OwnerUserId = me, IslandId = request.IslandId, StorageKey = request.StorageKey, MetadataJson = request.MetadataJson, IsPublic = request.IsPublic, CreatedAt = clock.GetUtcNow() }; db.PhotoSnapshots.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/discovery/photos/{item.Id}", item); }
    private static async Task<IResult> DeletePhotoAsync(Guid id, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.PhotoSnapshots.SingleOrDefaultAsync(x => x.Id == id && x.OwnerUserId == me, ct); if (item is null) return Results.NotFound(); db.PhotoSnapshots.Remove(item); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static bool User(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirstValue(JwtRegisteredClaimNames.Sub), out id);
    private static Task<bool> CanEnter(LifeVerseDbContext db, Guid islandId, Guid userId, CancellationToken ct) => db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == userId || db.IslandPermissions.Any(p => p.IslandId == islandId && p.UserId == userId && p.RevokedAt == null && p.Permission == "enter")), ct);
}
